import { useRef } from "react";

function SearchBox() {
  // Data shape: { current: null } until the input is committed.
  const inputRef = useRef(null);

  return (
    <>
      <input ref={inputRef} placeholder="Search hotels" />
      <button onClick={() => inputRef.current?.focus()}>
        Focus the field
      </button>
    </>
  );
}

import { useEffect, useRef } from "react";

function AutoFocusField() {
  const fieldRef = useRef(null);

  useEffect(() => {
    // The effect runs after the input exists, so the node is not null here.
    const field = fieldRef.current;
    if (!field) return;

    field.focus();
    field.select();
  }, []);

  return <input ref={fieldRef} defaultValue="Budapest" />;
}

import { useRef } from "react";

function SaveButton({ onSave }) {
  // Data shape: false, or true once a save has started.
  const savingRef = useRef(false);

  async function handleClick() {
    if (savingRef.current) return; // ignore a second click
    savingRef.current = true;

    try {
      await onSave();
    } finally {
      // Always release the flag, even when the request fails.
      savingRef.current = false;
    }
  }

  return <button onClick={handleClick}>Save</button>;
}

import { useRef, useState } from "react";

function ClickCounter() {
  const clicksRef = useRef(0);
  const [renders, setRenders] = useState(0);

  return (
    <section>
      <button
        onClick={() => {
          clicksRef.current += 1;
          console.log(clicksRef.current); // updates immediately
        }}
      >
        Log a click
      </button>

      <button onClick={() => setRenders((value) => value + 1)}>
        Render
      </button>

      {/* This number looks stale until another render happens. */}
      <p>Clicks in ref: {clicksRef.current}</p>
      <p>Renders: {renders}</p>
    </section>
  );
}

import { useRef } from "react";

function Index({ rows }) {
  // Wrong: buildIndex(rows) runs on every render, result discarded.
  // const indexRef = useRef(buildIndex(rows));

  // Right: build once, on the first render that needs the index.
  const indexRef = useRef(null);
  if (indexRef.current === null) {
    indexRef.current = buildIndex(rows);
  }

  // useRef does not call a function argument, it stores it.
  const callbackRef = useRef(() => rows.length);
  console.log(typeof callbackRef.current); // "function"

  return null;
}

function buildIndex(rows) {
  return new Map(rows.map((row) => [row.hotel_id, row]));
}

import { useEffect, useRef, useState } from "react";

function Ticker() {
  // Data shape: null, or the number returned by setInterval.
  const idRef = useRef(null);
  const [seconds, setSeconds] = useState(0);

  function start() {
    if (idRef.current !== null) return;

    idRef.current = setInterval(() => {
      setSeconds((value) => value + 1);
    }, 1000);
  }

  function stop() {
    if (idRef.current === null) return;

    clearInterval(idRef.current);
    idRef.current = null; // a later stop must not clear a reused id
  }

  useEffect(() => stop, []); // cleanup on unmount

  return (
    <>
      <p>{seconds} s</p>
      <button onClick={start}>Start</button>
      <button onClick={stop}>Stop</button>
    </>
  );
}

import { useEffect, useRef, useState } from "react";

function usePrevious(value) {
  const previousRef = useRef(undefined);

  useEffect(() => {
    previousRef.current = value;
  }, [value]);

  return previousRef.current;
}

function CityFilter() {
  const [city, setCity] = useState("Budapest");
  const previousCity = usePrevious(city);

  return (
    <section>
      <input value={city} onChange={(event) => setCity(event.target.value)} />
      <p>Now: {city}</p>
      <p>Before: {previousCity ?? "(none)"}</p>
    </section>
  );
}

import { useEffect, useRef, useState } from "react";

function LoginForm() {
  const emailRef = useRef(null);
  const [error, setError] = useState("");

  useEffect(() => {
    // Focus again whenever a new error appears.
    if (error) emailRef.current?.focus();
  }, [error]);

  function handleSubmit(event) {
    event.preventDefault();
    const email = event.target.customer_email.value;

    if (!email.includes("@")) {
      setError("Enter a valid email address.");
      return;
    }

    setError("");
  }

  return (
    <form onSubmit={handleSubmit}>
      <input ref={emailRef} name="customer_email" />
      {error && <p role="alert">{error}</p>}
      <button>Sign in</button>
    </form>
  );
}

import { useEffect, useRef } from "react";

function MessageList({ messages }) {
  // Marker placed after the last message.
  const endRef = useRef(null);

  useEffect(() => {
    // Runs after the new message is in the DOM.
    endRef.current?.scrollIntoView({ block: "end", behavior: "smooth" });
  }, [messages.length]);

  return (
    <div className="messages">
      {messages.map((message) => (
        <p key={message.id}>{message.text}</p>
      ))}
      <div ref={endRef} />
    </div>
  );
}

import { useRef } from "react";

function Clip({ src }) {
  const videoRef = useRef(null);

  async function play() {
    try {
      await videoRef.current?.play();
    } catch (error) {
      // Autoplay policy or a source that is not ready yet.
      console.log("play failed", error.name);
    }
  }

  return (
    <>
      <video ref={videoRef} src={src} muted playsInline preload="metadata" />
      <button onClick={play}>Play</button>
      <button onClick={() => videoRef.current?.pause()}>Pause</button>
      <button
        onClick={() => {
          if (videoRef.current) videoRef.current.currentTime = 0;
        }}
      >
        Restart
      </button>
    </>
  );
}

import { useCallback, useState } from "react";

function MeasuredBox() {
  const [height, setHeight] = useState(0);

  // Stable identity, otherwise React detaches and reattaches each render.
  const measure = useCallback((node) => {
    if (!node) return;
    setHeight(node.getBoundingClientRect().height);
  }, []);

  return (
    <section>
      <div ref={measure} className="box">
        Content with an unknown height
      </div>
      <p>Height: {height} px</p>
    </section>
  );
}

import { useEffect, useRef } from "react";

function FadeInBox() {
  const boxRef = useRef(null);
  // Data shape: 0 when no frame is pending, otherwise the frame id.
  const frameRef = useRef(0);
  const startRef = useRef(0);

  useEffect(() => {
    startRef.current = performance.now();

    const tick = (now) => {
      // Read the node again; it may have left the page since the last frame.
      const box = boxRef.current;
      if (!box) return;

      const progress = Math.min((now - startRef.current) / 1000, 1);
      box.style.opacity = String(progress); // style changes are safe
      frameRef.current = requestAnimationFrame(tick);
    };

    frameRef.current = requestAnimationFrame(tick);

    return () => {
      // Stop the loop and clear the stored id.
      cancelAnimationFrame(frameRef.current);
      frameRef.current = 0;
    };
  }, []);

  return <div ref={boxRef} style={{ opacity: 0 }}>Fading in</div>;
}

import { forwardRef, useImperativeHandle, useRef } from "react";

const FancyInput = forwardRef(function FancyInput(props, ref) {
  const inputRef = useRef(null);

  useImperativeHandle(ref, () => ({
    focus() {
      inputRef.current?.focus();
    },
    clear() {
      if (inputRef.current) inputRef.current.value = "";
    },
  }), []);

  return <input ref={inputRef} {...props} />;
});

function Toolbar() {
  const fancyRef = useRef(null);

  return (
    <section>
      <FancyInput ref={fancyRef} placeholder="Hotel name" />
      <button onClick={() => fancyRef.current?.focus()}>Focus</button>
      <button onClick={() => fancyRef.current?.clear()}>Clear</button>
    </section>
  );
}

